template <class T>
struct Storage {
  T value{};
  void reset() { value = T{}; }
};
template <class T>
struct Cache : Storage<T> {
  void clear() { reset(); }
};

int main() { Cache<int> c; c.clear(); }

template <class T>
struct Cache : Storage<T> {
  void clear() {
    this->reset();  // now dependent
  }
};

void handle(long) { std::cout << "long\n"; }
template <class T>
void handle(T)    { std::cout << "T\n"; }
void handle(int)  { std::cout << "int\n"; }

int main() {
  short s = 1;
  handle(1);
  handle(1L);
  handle(s);
}

void handle(long) { std::cout << "long\n"; }
void handle(int)  { std::cout << "int\n"; }

int main() {
  short s = 1;
  handle(s);  // int: promotion wins
}
